flow.typescript:
// D22 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_flow.ts   (ANTHROPIC_API_KEY가 있으면 fetch로 실제 Claude 호출, 없으면 모의 응답)
//   [대체 경로] 키가 없으면 키워드 규칙으로 답하는 모의 LLM을 쓴다. 나머지(이력·점검·비용)는 실제 로직이다.
type Msg = { role: string; content: string };
type Reply = { text: string; inTok: number; outTok: number };

const SYSTEM = "너는 한국어 음성 비서야. 한두 문장, 80자 안쪽의 짧은 구어체로 답해. 목록·마크다운·이모지는 쓰지 마.";
const PRICE = { inp: 0.1, out: 0.5 }; // 100만 토큰당 USD (참고값)
const MD = /(^\s*([-*•]|\d+[.)])\s)|[*#`|]/m;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

async function ask(system: string, messages: Msg[], maxTokens: number = 150): Promise<Reply> {
  const key = process.env.ANTHROPIC_API_KEY;
  if (key) {
    // 실제 경로: 키가 있을 때만
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
      body: JSON.stringify({ model: "claude-haiku-5-5", system, messages, max_tokens: maxTokens }),
    });
    const j = (await res.json()) as { content: { text: string }[]; usage: { input_tokens: number; output_tokens: number } };
    return { text: j.content[0].text, inTok: j.usage.input_tokens, outTok: j.usage.output_tokens };
  }
  const last = messages[messages.length - 1].content; // 모의 경로
  const seen = messages.map((m) => m.content).join(" ");
  let text = "네, 알겠어요.";
  if (last.includes("이름") && seen.includes("지민")) text = "지민 님이라고 하셨어요.";
  else if (last.includes("날씨")) text = "실시간 날씨는 지금 확인할 수 없어요.";
  return { text, inTok: Math.floor((system + seen).length / 2), outTok: Math.floor(text.length / 2) };
}

function voiceLint(text: string, maxChars: number = 80, maxSent: number = 2): boolean {
  const sents = text.trim().split(/(?<=[.!?])\s+|\n+/).filter((s) => s.trim() !== "");
  return text.length <= maxChars && sents.length <= maxSent && !MD.test(text);
}

class Conversation {
  system: string;
  maxTurns: number;
  turns: Msg[] = [];
  constructor(system: string, maxTurns: number = 2) {
    this.system = system;
    this.maxTurns = maxTurns;
  }
  messages(userText: string): Msg[] {
    const recent = this.turns.slice(-this.maxTurns * 2); // 한 턴 = user + assistant 메시지 2개
    return [...recent, { role: "user", content: userText }];
  }
  commit(userText: string, reply: string): void {
    this.turns.push({ role: "user", content: userText }, { role: "assistant", content: reply });
  }
}

const conv = new Conversation(SYSTEM);
let cost = 0;
for (const q of ["안녕, 내 이름은 지민이야.", "내일 날씨 어때?", "내 이름이 뭐였지?"]) {
  const r = await ask(SYSTEM, conv.messages(q));
  conv.commit(q, r.text);
  cost += (r.inTok * PRICE.inp + r.outTok * PRICE.out) / 1e6;
  console.log(`사용자: ${q}\n비서  : ${r.text}  (입력 ${r.inTok} · 출력 ${r.outTok} 토큰)`);
}
console.log(`3턴 비용 약 ${cost.toFixed(6)} USD · 마지막 답 음성 점검 ${voiceLint(conv.turns[5].content)}`);
check(conv.turns.length === 6 && conv.messages("다음").length === 5 && voiceLint("네, 알겠어요.") && !voiceLint("- 목록 **굵게**"), "3턴이면 메시지 6개, 창(2턴)을 쓰면 다음 요청은 4+1=5개입니다.");

anatomy.typescript:
// D22 · Part 1 · 세 API 비교 (요청 구조) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_anatomy.ts   (요청 본문(JSON)만 만들어 비교하므로 키·인터넷 불필요)
//   [대체 경로] 실제 호출은 하지 않는다. 세 회사의 요청 모양을 같은 입력에서 만들어 공통점·차이를 확인한다.
type Msg = { role: string; content: string };
const SYSTEM = "한두 문장으로 짧게 답해.";
const USER = "내일 서울 날씨 어때?";
const MAX_TOKENS = 150;
const TURNS: Msg[] = [
  { role: "user", content: "안녕" },
  { role: "assistant", content: "안녕하세요." },
  { role: "user", content: USER },
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// messages API: system은 따로, max_tokens 필수
const claudeBody = (): Record<string, unknown> => ({ model: "claude-haiku-5-5", system: SYSTEM, max_tokens: MAX_TOKENS, stream: true, messages: TURNS });
// Responses API: instructions + input
const openaiBody = (): Record<string, unknown> => ({ model: "gpt-6-luna", instructions: SYSTEM, max_output_tokens: MAX_TOKENS, stream: true, input: TURNS });
// generateContent: 역할 이름이 user / model
const geminiBody = (): Record<string, unknown> => ({
  system_instruction: { parts: [{ text: SYSTEM }] },
  generationConfig: { maxOutputTokens: MAX_TOKENS },
  contents: TURNS.map((m) => ({ role: m.role === "assistant" ? "model" : "user", parts: [{ text: m.content }] })),
});

const bodies: Record<string, Record<string, unknown>> = { claude: claudeBody(), openai: openaiBody(), gemini: geminiBody() };
for (const [name, b] of Object.entries(bodies)) console.log(`${name.padEnd(7)} 최상위 키:`, Object.keys(b).sort());
const common = Object.values(bodies).every((b) => {
  const t = JSON.stringify(b);
  return t.includes(SYSTEM) && t.includes(USER) && t.includes(String(MAX_TOKENS));
});
const gContents = bodies.gemini.contents as { role: string }[];
check(common && gContents[1].role === "model" && "system" in bodies.claude, "세 API 모두 시스템 지시·대화·길이 상한이 들어가고, Gemini만 assistant 대신 model을 씁니다.");

stream.python:
# D22 · Part 2 · Streaming 이벤트 통일 — 단독 실행 완성 코드 (Python 3.11)
# pip install anthropic==2.11.0
# 실행: python d22_stream.py   (ANTHROPIC_API_KEY가 있으면 실제 Claude 스트림도 같은 함수로 읽음)
#   [대체 경로] 키가 없으면 세 회사의 이벤트 모양을 흉내 낸 가짜 이벤트 목록을 쓴다.
import os
import time

WORDS = ["내일", " 서울은", " 맑고", " 최고", " 18도예요."]
FAKE = {   # 회사마다 다른 이벤트 모양 (모의)
    "claude": [{"type": "content_block_delta", "delta": {"type": "text_delta", "text": w}} for w in WORDS],
    "openai": [{"type": "response.output_text.delta", "delta": w} for w in WORDS] + [{"type": "response.completed"}],
    "gemini": [{"candidates": [{"content": {"parts": [{"text": w}]}}]} for w in WORDS],
}


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def pieces(provider: str, events: list):
    """회사마다 다른 이벤트에서 '글 조각'만 꺼내 똑같은 generator로 내준다."""
    for ev in events:
        if provider == "claude" and ev["type"] == "content_block_delta":
            yield ev["delta"]["text"]
        elif provider == "openai" and ev["type"] == "response.output_text.delta":
            yield ev["delta"]
        elif provider == "gemini":
            yield ev["candidates"][0]["content"]["parts"][0]["text"]


def stream_real(question: str):
    import anthropic                                   # 실제 경로: 키가 있을 때만
    with anthropic.Anthropic().messages.stream(model="claude-haiku-5-5", max_tokens=100,
                                               messages=[{"role": "user", "content": question}]) as s:
        yield from s.text_stream


def run(gen):
    t0, ttft, out = time.perf_counter(), None, []
    for p in gen:
        if ttft is None:
            ttft = time.perf_counter() - t0            # 첫 조각이 온 시각 = TTFT
        out.append(p)
    return "".join(out), ttft


results = {p: run(pieces(p, ev)) for p, ev in FAKE.items()}
for p, (text, ttft) in results.items():
    print(f"{p:<7} TTFT {ttft * 1000:.2f}ms → {text}")
if os.environ.get("ANTHROPIC_API_KEY"):
    text, ttft = run(stream_real("서울은 어느 나라 수도야? 한 문장으로."))
    print(f"실제 Claude TTFT {ttft:.2f}초 → {text}")
check({t for t, _ in results.values()} == {"내일 서울은 맑고 최고 18도예요."},
      "세 회사 모두 같은 글 조각 순서로 합쳐져야 해요.")

stream.typescript:
// D22 · Part 2 · Streaming 이벤트 통일 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_stream.ts   (ANTHROPIC_API_KEY가 있으면 fetch 스트림도 같은 함수로 읽음)
//   [대체 경로] 키가 없으면 세 회사의 이벤트 모양을 흉내 낸 가짜 이벤트 목록을 쓴다.
type Ev = Record<string, any>;
const WORDS = ["내일", " 서울은", " 맑고", " 최고", " 18도예요."];
const FAKE: Record<string, Ev[]> = {
  claude: WORDS.map((w) => ({ type: "content_block_delta", delta: { type: "text_delta", text: w } })),
  openai: [...WORDS.map((w) => ({ type: "response.output_text.delta", delta: w })), { type: "response.completed" }],
  gemini: WORDS.map((w) => ({ candidates: [{ content: { parts: [{ text: w }] } }] })),
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function* pieces(provider: string, events: Ev[]): Generator<string> {
  // 회사마다 다른 이벤트에서 '글 조각'만 꺼내 똑같은 generator로 내준다
  for (const ev of events) {
    if (provider === "claude" && ev.type === "content_block_delta") yield ev.delta.text;
    else if (provider === "openai" && ev.type === "response.output_text.delta") yield ev.delta;
    else if (provider === "gemini") yield ev.candidates[0].content.parts[0].text;
  }
}

async function* streamReal(question: string, key: string): AsyncGenerator<string> {
  // 실제 경로: 키가 있을 때만 (SSE 줄에서 text_delta만 꺼냄)
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model: "claude-haiku-5-5", max_tokens: 100, stream: true, messages: [{ role: "user", content: question }] }),
  });
  const decoder = new TextDecoder();
  let buf = "";
  for await (const chunk of res.body as unknown as AsyncIterable<Uint8Array>) {
    buf += decoder.decode(chunk, { stream: true });
    const lines = buf.split("\n");
    buf = lines.pop() ?? "";
    for (const line of lines) {
      if (!line.startsWith("data: ")) continue;
      const ev = JSON.parse(line.slice(6)) as Ev;
      if (ev.type === "content_block_delta") yield ev.delta.text;
    }
  }
}

async function run(gen: Iterable<string> | AsyncIterable<string>): Promise<[string, number]> {
  const t0 = performance.now();
  let ttft = -1;
  const out: string[] = [];
  for await (const p of gen) {
    if (ttft < 0) ttft = performance.now() - t0; // 첫 조각이 온 시각 = TTFT
    out.push(p);
  }
  return [out.join(""), ttft];
}

const results: Record<string, [string, number]> = {};
for (const [p, ev] of Object.entries(FAKE)) results[p] = await run(pieces(p, ev));
for (const [p, [text, ttft]] of Object.entries(results)) console.log(`${p.padEnd(7)} TTFT ${ttft.toFixed(2)}ms → ${text}`);
const key = process.env.ANTHROPIC_API_KEY;
if (key) {
  const [text, ttft] = await run(streamReal("서울은 어느 나라 수도야? 한 문장으로.", key));
  console.log(`실제 Claude TTFT ${(ttft / 1000).toFixed(2)}초 → ${text}`);
}
check(new Set(Object.values(results).map((r) => r[0])).size === 1 && results.claude[0] === "내일 서울은 맑고 최고 18도예요.", "세 회사 모두 같은 글 조각 순서로 합쳐져야 해요.");

cost.typescript:
// D22 · Part 3 · 비용 계산기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_cost.ts   (단가는 참고용 예시값 — 실제 값은 각 회사 공식 가격표 확인)
type Price = { inp: number; out: number };
const PRICES: Record<string, Price> = { A: { inp: 0.1, out: 0.5 }, B: { inp: 0.54, out: 4.5 }, local: { inp: 0, out: 0 } }; // 100만 토큰당 USD

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const turnCost = (inTok: number, outTok: number, pr: Price): number => (inTok * pr.inp + outTok * pr.out) / 1e6; // 출력 단가의 키는 out

const rows: Record<string, number> = {};
for (const [name, pr] of Object.entries(PRICES)) {
  rows[name] = turnCost(900, 60, pr);
  console.log(`${name.padEnd(6)} 1턴 ${rows[name].toFixed(6)} USD · 1000턴 ${(rows[name] * 1000).toFixed(4)} USD`);
}
// 이력 전체를 매번 보내면 입력 토큰이 턴마다 늘어난다 (턴당 +120토큰)
const turns = Array.from({ length: 30 }, (_, t) => t);
const full = turns.reduce((s, t) => s + turnCost(200 + 120 * t, 60, PRICES.B), 0);
const windowed = turns.reduce((s, t) => s + turnCost(200 + 120 * Math.min(t, 4), 60, PRICES.B), 0); // 최근 4턴만
console.log(`30턴 합계: 전체 이력 ${full.toFixed(5)} USD · 최근 4턴 ${windowed.toFixed(5)} USD`);
check(rows.local === 0 && Math.abs(rows.A - 0.00012) < 1e-9 && windowed < full, "1턴 = (입력×단가 + 출력×단가) / 100만, 창을 쓰면 더 싸요.");

lint.typescript:
// D22 · Part 4 · 음성용 답 점검기 voiceLint — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_lint.ts   (인터넷 불필요)
const MAX_CHARS = 80;
const MAX_SENT = 2;
const MD = /(^\s*([-*•]|\d+[.)])\s)|[*#`|]|\[[^\]]*\]\(/m;
const EMOJI = /[\u{1F300}-\u{1FAFF}☀-➿]/u;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function voiceLint(text: string, maxChars: number = MAX_CHARS, maxSent: number = MAX_SENT): Record<string, number | boolean> {
  const sents = text.trim().split(/(?<=[.!?])\s+|\n+/).filter((s) => s.trim() !== "").length;
  const r = {
    글자: [...text].length,
    문장: sents,
    마크다운: MD.test(text),
    이모지: EMOJI.test(text),
    영어: (text.match(/[A-Za-z]{3,}/g) ?? []).length,
  };
  return { ...r, ok: r.글자 <= maxChars && r.문장 <= maxSent && !r.마크다운 && !r.이모지 };
}

const samples = [
  "내일 서울은 맑고 낮 최고 18도예요. 우산은 필요 없어요.",
  "## 내일 날씨\n- **최고 기온**: 18도\n- 강수 확률: 10% ☀️",
  "네. 알겠어요. 바로 옮길게요. 3시 30분으로 바꿨어요. 더 필요한 것 있나요?",
];
const oks: boolean[] = [];
for (const s of samples) {
  const r = voiceLint(s);
  oks.push(r.ok as boolean);
  console.log(s.replace(/\n/g, " / ").slice(0, 34), "→", r);
}
check(oks.join() === "true,false,false", "첫 문장만 통과: 둘째는 마크다운·이모지, 셋째는 문장이 5개입니다.");

history.typescript:
// D22 · Part 5 · 이력 창 · 요약 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_history.ts   (요약은 LLM 대신 '지난 턴에서 이름·약속을 뽑는 규칙'으로 대신함)
//   [대체 경로] 실제로는 LLM에게 요약을 시키지만 여기서는 정규식으로 핵심 사실만 모은다.
type Msg = { role: string; content: string };
const SCRIPT = ["안녕, 내 이름은 지민이야.", "나 금요일 오후 2시에 치과 예약이 있어.", "점심 메뉴 하나만 추천해 줘.", "그럼 저녁은 뭐가 좋을까?", "주말에 갈 만한 산책 장소 있을까?"];
const FACT = /이름은 \S+|금요일 오후 \d시/;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class Conversation {
  maxTurns: number;
  summarize: boolean;
  turns: Msg[] = [];
  facts: string[] = [];
  constructor(maxTurns: number, summarize: boolean = false) {
    this.maxTurns = maxTurns;
    this.summarize = summarize;
  }
  messages(userText: string): Msg[] {
    const recent = this.maxTurns ? this.turns.slice(-this.maxTurns * 2) : [...this.turns]; // 한 턴 = 메시지 2개
    const head: Msg[] = this.facts.length
      ? [{ role: "user", content: "[지난 대화 요약] " + this.facts.join("; ") }, { role: "assistant", content: "알겠어요." }]
      : [];
    return [...head, ...recent, { role: "user", content: userText }];
  }
  commit(userText: string, reply: string): void {
    this.turns.push({ role: "user", content: userText }, { role: "assistant", content: reply });
    if (this.summarize) {
      this.facts = this.turns.filter((t) => t.role === "user").map((t) => FACT.exec(t.content)).filter((m) => m !== null).map((m) => m[0]);
    }
  }
}

function remembers(conv: Conversation): boolean {
  const text = conv.messages("내 이름이 뭐였지?").map((m) => m.content).join(" ");
  return text.includes("지민") && text.includes("금요일");
}

const result: Record<string, [number[], boolean]> = {};
const setups: Record<string, Conversation> = { "전체 이력": new Conversation(0), "최근 2턴": new Conversation(2), "최근 2턴 + 요약": new Conversation(2, true) };
for (const [name, conv] of Object.entries(setups)) {
  const sizes: number[] = [];
  for (const q of SCRIPT) {
    sizes.push(conv.messages(q).length);
    conv.commit(q, "네.");
  }
  result[name] = [sizes, remembers(conv)];
  console.log(`${name.padEnd(14)} 보낸 메시지 수 [${sizes.join(", ")}] · 이름·약속 기억 ${result[name][1]}`);
}
check(result["전체 이력"][0].join() === "1,3,5,7,9" && !result["최근 2턴"][1] && result["최근 2턴 + 요약"][1], "전체는 계단식으로 늘고, 창만 쓰면 잊고, 창 + 요약은 기억해야 해요.");

bargein.typescript:
// D22 · Part 5 · 끼어들기 저장 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_bargein.ts   (스피커 대신 '초당 N글자 읽는다'는 시간 계산으로 대신함)
//   [대체 경로] 실제 TTS 재생 없이 재생 시간(초)으로 '실제로 말한 글자 수'를 계산한다.
type Msg = { role: string; content: string };
const CHARS_PER_SEC = 8; // 모의 TTS 속도: 초당 8글자
const REPLY = "내일 서울은 맑고 낮 최고 기온은 18도예요. 아침에는 조금 쌀쌀하니 겉옷을 챙기세요.";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const spokenChars = (playedSec: number): number => Math.min(REPLY.length, Math.floor(playedSec * CHARS_PER_SEC));

function commit(turns: Msg[], userText: string, reply: string, spoken: number | null = null): void {
  const said = spoken === null ? reply : reply.slice(0, spoken).trimEnd() + " …(사용자가 끼어듦)"; // 말한 만큼만 저장
  turns.push({ role: "user", content: userText }, { role: "assistant", content: said });
}

const turns: Msg[] = [];
const n = spokenChars(2.5); // 2.5초 말하다 사용자가 끼어듦
commit(turns, "내일 날씨 알려 줘", REPLY, n);
const saved = turns[turns.length - 1].content;
console.log(`전체 ${REPLY.length}자 중 ${n}자만 말함 → 저장: ${saved}`);
const full: Msg[] = [];
commit(full, "내일 날씨 알려 줘", REPLY);
check(n === 20 && saved.endsWith("(사용자가 끼어듦)") && !saved.includes("겉옷") && full[1].content.includes("겉옷"), "끼어들면 사용자가 듣지 못한 뒷부분은 이력에 남기지 않아요.");

thinking.typescript:
// D22 · Part 2 · 생각 모드와 TTFT — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_thinking.ts   (모델 없이 '생각 토큰 수 ÷ 생성 속도'만큼 첫 글자가 늦어진다고 계산)
//   [대체 경로] 실제 API 대신 생각 예산별 TTFT를 식으로 계산한다.
const TPS = 60; // 모의: 초당 60토큰
const BASE_TTFT = 0.3; // 생각 없이 첫 글자까지 0.3초
const BUDGETS: Record<string, number> = { minimal: 0, low: 512, medium: 2048, high: 8192 }; // 생각 토큰 상한

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 생각 토큰이 다 나올 때까지 글자는 안 나온다
const ttft = (level: string, usedRatio: number = 0.1): number => BASE_TTFT + (BUDGETS[level] * usedRatio) / TPS;

const rows: Record<string, number> = {};
for (const lv of Object.keys(BUDGETS)) {
  rows[lv] = ttft(lv);
  console.log(`${lv.padEnd(8)} 생각 ${String(BUDGETS[lv]).padStart(5)}토큰 → 첫 글자까지 약 ${rows[lv].toFixed(2)}초 ${rows[lv] <= 1.5 ? "(음성 비서 OK)" : "(음성에는 너무 느림)"}`);
}
const voiceOk = Object.keys(rows).filter((lv) => rows[lv] <= 1.5);
check(voiceOk.join() === "minimal,low" && rows.high > 5 * rows.minimal, "음성 비서는 생각을 minimal·low로 줄여 TTFT를 지킵니다.");

keys.typescript:
// D22 · Part 1 · API 키 안전 점검 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d22_keys.ts   (가짜 키로만 검사하므로 진짜 키·인터넷 불필요)
// 가짜 키는 실행할 때 조립한다 (저장소에 키 모양 문자열을 남기지 않기 위해)
const FAKE = "sk-ant-" + "A1b2C3d4".repeat(3);
const SECRET = /(sk-ant-[A-Za-z0-9_-]{16,}|AIza[0-9A-Za-z_-]{20,}|sk-[A-Za-z0-9]{20,})/g;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const mask = (key: string): string => (key.length > 12 ? key.slice(0, 7) + "…" + key.slice(-2) : "***");
const scan = (name: string, text: string): string[] => [...text.matchAll(SECRET)].map((m) => `${name}: 키 모양 발견 → ${mask(m[0])}`);

const files: Record<string, string> = {
  "app.ts": 'const client = new Anthropic({ apiKey: "' + FAKE + '" });\n', // 나쁜 예: 코드에 직접
  "good.ts": "const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });\n",
  ".env.example": "ANTHROPIC_API_KEY=\n",
  "log.txt": "요청 헤더 x-api-key: " + FAKE + "\n",
};
const bad = Object.entries(files).flatMap(([n, t]) => scan(n, t));
console.log(bad.join("\n"));
check(bad.map((m) => m.split(":")[0]).join() === "app.ts,log.txt" && !bad.join("\n").includes(FAKE), "코드·로그의 키는 잡고, 환경 변수 읽기와 .env.example은 통과, 출력엔 마스킹된 키만.");
